package com.example.demo.common.base.entity;


import com.example.demo.common.event.DomainEvent;

import java.util.List;

/**
 * Marker interface for Domain-Driven Design Aggregate Roots
 *
 * Aggregate Root responsibilities:
 * - Entry point for all operations on the aggregate
 * - Ensures aggregate consistency
 * - Publishes domain events
 * - Controls access to internal entities
 *
 * @author Architecture Team
 * @version 1.0
 */
public interface AggregateRoot {

    /**
     * Get domain events generated by this aggregate
     * Events should be cleared after publishing
     *
     * @return list of domain events
     */
    List<DomainEvent> getDomainEvents();

    /**
     * Clear domain events after publishing
     */
    void clearDomainEvents();

    /**
     * Register a domain event
     *
     * @param event the domain event to register
     */
    void registerEvent(DomainEvent event);
}